# Databricks notebook source
# MAGIC %md
# MAGIC # Actuary in a Box on Databricks
# MAGIC Read a claims triangle from Unity Catalog, run the existing reserving harness, and save the evidence to Delta. The draft report is generated by the same harness used outside Databricks.
# MAGIC
# MAGIC Use `raa` with `mack` to show the estimate and model review. Use `gapped` with either method to show the validation gate.
# MAGIC
# MAGIC Add the sibling harness wheel in the notebook's **Environment** pane and apply the change before running. Use a writable Unity Catalog schema. A blank catalog uses the notebook's current catalog.

# COMMAND ----------

from databricks_demo.reserving import read_triangle, run_reserving, save_run, seed_triangles, table_names

dbutils.widgets.dropdown("dataset", "raa", ["raa", "gapped"], "Sample triangle")
dbutils.widgets.dropdown("method", "mack", ["mack", "chain_ladder"], "Reserving method")
dbutils.widgets.text("catalog", "", "Unity Catalog catalog")
dbutils.widgets.text("schema", "default", "Unity Catalog schema")
dbutils.widgets.text("job_run_id", "", "Lakeflow job run ID")

# COMMAND ----------

# MAGIC %md
# MAGIC ## 1. Load the sample triangles
# MAGIC Seed the managed Delta input table once. Re-running this cell keeps the existing observations. The samples are public RAA data and a deliberately gapped fixture from the repository.

# COMMAND ----------

triangles, history = table_names(
    spark, dbutils.widgets.get("catalog").strip(), dbutils.widgets.get("schema").strip()
)
seed_triangles(spark, triangles)
display(spark.sql(f"""
    SELECT dataset, count(*) AS observations, min(origin) AS first_origin, max(origin) AS last_origin
    FROM {triangles}
    GROUP BY dataset
    ORDER BY dataset
"""))

# COMMAND ----------

# MAGIC %md
# MAGIC ## 2. Run the validation gate and reserve review
# MAGIC The run reads a specific Delta version. Each attempt saves its input hash, stage exit codes, model results and original artifacts. A structural gap stops the fit and still leaves a run history entry.

# COMMAND ----------

dataset = dbutils.widgets.get("dataset")
method = dbutils.widgets.get("method")
source_version, csv_input = read_triangle(spark, triangles, dataset)
result = run_reserving(csv_input, dataset, method, triangles, source_version, dbutils.widgets.get("job_run_id"))
save_run(spark, history, result)
attempt_id = result["attempt_id"]

print(f"Outcome: {result['status']} | Delta input version: {source_version}")
print(f"Run history: {history} | Attempt: {attempt_id}")
if result["status"] == "execution_failed":
    raise RuntimeError(f"Reserving execution failed. See the saved evidence for attempt {attempt_id}.")

# COMMAND ----------

# MAGIC %md
# MAGIC ## 3. Inspect the audit history and draft
# MAGIC The results below are read back from Delta. An estimate awaiting review is a draft. A blocked run has validation evidence and no model output.

# COMMAND ----------

display(spark.sql(f"""
    SELECT started_at, dataset, method, status, validation_verdict, diagnostics_verdict,
           latest, ultimate, ibnr, mack_se, stage_exit_codes, source_version, job_run_id, attempt_id
    FROM {history}
    ORDER BY started_at DESC
    LIMIT 20
"""))

evidence = spark.sql(f"""
    SELECT artifacts['validation/validation.json'] AS validation, artifacts['model/report.html'] AS report
    FROM {history}
    WHERE attempt_id = :attempt_id
""", args={"attempt_id": attempt_id}).first()

# COMMAND ----------

import json

for check in json.loads(evidence["validation"])["checks"]:
    if check["verdict"] != "pass":
        print(f"{check['verdict'].upper()} | {check['check_id']} | {check['details']}")

if evidence["report"]:
    displayHTML(evidence["report"])
else:
    print("Validation blocked the fit. The evidence is saved in the run history.")
